import numpy as np

def invert_if_iso(A):
    A = np.array(A, dtype=float)
    n = A.shape[0]
    if A.shape != (n, n):
        return None
    if np.linalg.matrix_rank(A) < n:
        return None
    return (np.round(np.linalg.inv(A), 6) + 0.0).tolist()
